# 명제 논리 공식 = 재귀로 정의된 트리 (튜플로 표현)
CONN = {"not": 1, "and": 2, "or": 2, "implies": 2, "iff": 2}

def is_formula(f):
    if isinstance(f, str):                 # 기저: 명제 기호(원자 공식)
        return f.isidentifier()
    if isinstance(f, tuple) and f and f[0] in CONN:
        args = f[1:]                       # 귀납: 연결사 + 하위 공식
        return len(args) == CONN[f[0]] and all(map(is_formula, args))
    return False                           # 그 밖의 것은 공식이 아니다

tests = {
    "P": "P",
    "¬P": ("not", "P"),
    "¬P ∨ Q": ("or", ("not", "P"), "Q"),
    "P → (Q ∨ ¬P)": ("implies", "P", ("or", "Q", ("not", "P"))),
    "P ¬Q": ("P", ("not", "Q")),          # 연결사 없음
    "P + Q": ("+", "P", "Q"),             # 없는 연결사
    "¬(P, Q)": ("not", "P", "Q"),         # 인자 개수 틀림
}
for name, f in tests.items():
    print(f"{name:14s} {is_formula(f)}")

from itertools import product
def I(f, w):                                   # 해석 함수(5챕터)
    if isinstance(f, str): return w[f]
    op, *a = f; v = [I(g, w) for g in a]
    return {"not": lambda: not v[0], "and": lambda: v[0] and v[1], "or": lambda: v[0] or v[1],
            "implies": lambda: not v[0] or v[1], "iff": lambda: v[0] == v[1]}[op]()
def M(kb, S):                                  # M(KB): KB 의 모든 공식을 참으로 만드는 세계
    ws = (dict(zip(S, v)) for v in product([0, 1], repeat=len(S)))
    return [w for w in ws if all(I(f, w) for f in kb)]
S = ["Rain", "Wet"]
P = {(0, 0): 0.5, (0, 1): 0.1, (1, 0): 0.1, (1, 1): 0.3}   # 화면의 결합표
def prob(kb):                                  # P(KB) = Σ_{w∈M(KB)} P(w)
    return sum(P[(w["Rain"], w["Wet"])] for w in M(kb, S))
def cond(f, kb):                               # P(f | KB) = P(KB ∪ {f}) / P(KB)
    return prob(kb + [f]) / prob(kb)
print("P(Rain)             =", prob(["Rain"]))
print("P(Rain | Wet)       =", round(cond("Rain", ["Wet"]), 3))
print("P(Rain | Rain∨Wet)  =", round(cond("Rain", [("or", "Rain", "Wet")]), 3))
print("P(Wet | Rain→Wet)   =", round(cond("Wet", [("implies", "Rain", "Wet")]), 3))
for kb, f in [(["Rain", "Wet"], "Rain"), ([("not", "Rain")], "Rain")]:
    print(kb, f, "->", cond(f, kb))           # 1.0 = Yes, 0.0 = No
